import os
from collections import Counter

def count_word_frequency(results, word):
    if word in results:
        results[word] += 1
    else:
        results.setdefault(word, 1)

def top_word_frequencies(directory):
    files = []
    results = {}
    for f in os.listdir(directory):
        full_path = os.path.join(directory, f)
        try:
            with open(full_path, 'r') as f:
                files.append(f)
            for f in files:
                word_list = [word.lower() for word in f.rstrip().split()]
                for word in word_list:
                    count_word_frequency(results, word)
        except Exception as e:
            print(e)
    total_words = len(results)
    for word in sorted(results.keys()):
        count = results[word]
        if count!= total_words:
            results[word] = count/total_words

    return [k +'-->'+ str(v) for k, v in sorted(results.items(), key=lambda item: item[1], reverse=True)]

